import json

STORE = {}

def key(tid): return f"thread:{tid}"

def new_state(tid):
    return {"thread_id": tid, "step": 0, "log": []}

def step_and_checkpoint(state):
    state["step"] += 1
    state["log"].append(f"did step {state['step']}")
    STORE[key(state["thread_id"])] = json.dumps(state)  # checkpoint each step
    return state

def run(tid, total_steps, crash_at=None):
    blob = STORE.get(key(tid))
    state = json.loads(blob) if blob else new_state(tid)
    while state["step"] < total_steps:
        if crash_at is not None and state["step"] == crash_at:
            raise RuntimeError("process died")  # simulate a crash
        state = step_and_checkpoint(state)
    return state

# first attempt crashes after completing step 2
try:
    run("t-9", total_steps=4, crash_at=2)
except RuntimeError:
    pass

# second attempt resumes from the last checkpoint (step 2)
final = run("t-9", total_steps=4)
print(final["step"], final["log"])

