import json

class Checkpointer:
    def __init__(self):
        self._backend = {}  # key -> json blob

    def _key(self, thread_id: str) -> str:
        return f"agent:thread:{thread_id}"

    def save(self, thread_id: str, state: dict) -> None:
        # serialize to JSON so the backend only holds text
        self._backend[self._key(thread_id)] = json.dumps(state)

    def load(self, thread_id: str) -> dict | None:
        blob = self._backend.get(self._key(thread_id))
        return json.loads(blob) if blob is not None else None

    def resume_or_new(self, thread_id: str, factory) -> dict:
        existing = self.load(thread_id)
        # resume from checkpoint if present, otherwise build fresh state
        return existing if existing is not None else factory()

