import json

def key(thread_id: str) -> str:
    return f"agent:thread:{thread_id}"

def new_state(thread_id: str) -> dict:
    return {"thread_id": thread_id, "step": 0, "log": []}

def run(thread_id: str, store, total_steps: int) -> dict:
    blob = store.get(key(thread_id))
    # resume from checkpoint if present, else start fresh
    state = json.loads(blob) if blob is not None else new_state(thread_id)
    while state["step"] < total_steps:
        state["step"] += 1
        state["log"].append(f"step {state['step']}")
        store.set(key(thread_id), json.dumps(state))  # checkpoint each step
    return state

if __name__ == "__main__":
    class DictStore:
        def __init__(self): self.d = {}
        def get(self, k): return self.d.get(k)
        def set(self, k, v): self.d[k] = v

    s = DictStore()
    run("t-1", s, total_steps=2)          # complete 2 steps
    final = run("t-1", s, total_steps=4)  # resume, finish 3 and 4
    print(final["step"], final["log"])
